# -*- coding: utf-8 -*-
"""Код обмена и ссылка на бота: по ней сдают фото и видео сделки.

Как это выглядит на точке:

  1. Приложение придумывает короткий код и показывает ссылку с ним:
     `https://t.me/<бот>?start=p7KQ2M` (и QR на неё).
  2. Сотрудник открывает ссылку своим телефоном — бот сразу знает, КТО пришёл, по
     chat_id находит его в `users`. Это и есть оценщик сделки: отдельно спрашивать
     «кто проводил оценку» не нужно.
  3. Сотрудник шлёт боту видео и фото, бот складывает `file_id` в строку с этим кодом.
  4. Сделку с тем же кодом бот создаёт сам (ocenka_tg.py отдаёт ему посылку) и подставляет
     в неё это видео и эти фото.

Почему так: Оценка хранит медиа не файлами, а `file_id` Telegram — значит хранение
бесплатное и ничего своего поднимать не нужно. А главное, видео обязательно: без него
Оценка не открывает карточку сделки.

Код здесь только придумывается — в базу его пишет бот, когда сотрудник открывает ссылку.
С точки в базу Оценки хода нет: порт Postgres закрыт наружу.
"""
from __future__ import annotations

import secrets

# Код диктуют голосом и набирают руками, поэтому ни одной пары, которую легко спутать:
# нет O и 0, I и 1, B и 8, S и 5, Z и 2.
АЛФАВИТ = "ACDEFGHJKLMNPQRTUVWXY345679"


def новый_код(n: int = 6) -> str:
    return "".join(secrets.choice(АЛФАВИТ) for _ in range(n))


def ссылка(бот: str, код: str) -> str:
    """Готовая ссылка с командой: открывший её сразу попадает на нужную сделку."""
    бот = str(бот or "").strip().lstrip("@").removeprefix("https://t.me/").strip("/")
    return f"https://t.me/{бот}?start=p{код}"


# ---------------------------------------------------------------- ручная диагностика

# Пункты, которые сотрудник отмечает РУКАМИ — на экране программы, пока телефон клиента у
# него в руках. Здесь только то, чего не может ни кабель (он читает прошивку и привязку
# модулей), ни страница теста на телефоне клиента (браузер не нажмёт кнопку, не включит
# вибрацию и не посмотрит в лоток SIM).
# Экран, касание, камеры, динамик и микрофон прогоняет сам телефон — см. pintel_core.phonetest.
#
# Отмечают их ЗДЕСЬ, в программе, а не в боте: телефон лежит на столе рядом с кассой, а не
# рядом с чатом, и переключать восемь кнопок в Telegram, держа аппарат, — лишний шаг на
# ровном месте. Отметки едут в сделку посылкой, и бот кладёт их в карточку как есть.
#
# КОПИЯ списка из `deploy/оценка_бот/kiosk_core.py` (ПУНКТЫ): там он нужен, чтобы назвать
# отметки словами в карточке (и для старых сборок, которые ещё спрашивают их кнопками), а
# живут они в разных местах — бот на сервере, программа в exe. Расхождение сверяется тестом
# test_ocenka_tg.py, как и префикс кнопки сделки.
ПУНКТЫ = (
    ("keys", "Кнопки", "питание, громкость, бесшумный режим"),
    ("vibro", "Вибрация", "Taptic отзывается (браузер не умеет)"),
    ("bio", "Face ID", "разблокировка лицом или отпечатком"),
    ("charge", "Зарядка", "заряжается от кабеля"),
    ("net", "Связь", "SIM видна, сеть и Wi-Fi работают"),
    ("glue", "Герметик", "проклейка на месте, зазоров нет"),
    ("apple", "Детали Apple", "«Детали и обслуживание»: всё родное"),
    ("mdm", "Управление", "VPN и управление: чужих профилей нет"),
)


КЛЮЧИ = tuple(k for k, _, _ in ПУНКТЫ)
ЗАПЕЧАТАН = "sealed"                   # коробку не вскрывали — проверять нечего

# Сколько фото ждёт бот: экран с *#06#, лицевая, задняя (kiosk_core.ЭТАПЫ_ФОТО). Это нужно
# знать и здесь: программа на точке показывает, сколько уже дошло, и не даёт отправить
# сделку, пока медиа не собраны. Расхождение со списком бота ловит тест.
НУЖНО_ФОТО = 3


def пункты_словами(разделитель: str = " · ") -> str:
    """Короткие надписи пунктов — для экрана программы: сотрудник видит, что его ждёт, и
    проверяет телефон, пока он в руках."""
    return разделитель.join(к for _, к, _ in ПУНКТЫ)


def разобрать(сырое) -> dict:
    """Что угодно → отметки: только наши ключи и только да/нет.

    Те же правила, что в обработчике бота (`kiosk_core.диагностика_разобрать`): отметки
    едут туда посылкой, и разойтись в том, что считать отметкой, нельзя. Непонятное
    отбрасываем молча — это наши же данные, полежавшие между версиями программы.
    """
    if isinstance(сырое, (bytes, bytearray)):
        сырое = bytes(сырое).decode("utf-8", "replace")
    if isinstance(сырое, str):
        import json
        try:
            сырое = json.loads(сырое or "{}")
        except Exception:                                        # noqa: BLE001
            return {}
    if not isinstance(сырое, dict):
        return {}
    из = {}
    for k, v in сырое.items():
        if k == ЗАПЕЧАТАН and v:
            из[ЗАПЕЧАТАН] = True
        elif k in КЛЮЧИ and isinstance(v, bool):
            из[k] = v
    return из


def переключить(отметки, ключ: str) -> dict:
    """Нажатие на пункт: не отмечено → работает → не работает → не отмечено.

    Третьего состояния «не проверял» нет намеренно: оно стало бы способом пропустить шаг.
    Нечем проверить (нет SIM, телефон не включается) — это «не работает», и сделка уходит
    на оценку человеку. Ошибка в эту сторону стоит оценки человеком, обратная — денег.
    """
    d = dict(разобрать(отметки))
    if ключ == ЗАПЕЧАТАН:
        return {} if d.get(ЗАПЕЧАТАН) else {ЗАПЕЧАТАН: True}
    if ключ not in КЛЮЧИ:
        return d
    d.pop(ЗАПЕЧАТАН, None)                 # отмечают по пунктам — значит коробка вскрыта
    текущее = d.get(ключ)
    if текущее is None:
        d[ключ] = True
    elif текущее is True:
        d[ключ] = False
    else:
        d.pop(ключ, None)
    return d


def не_отмечено(отметки) -> list:
    """Отметки диагностики → пункты без ответа, короткими надписями."""
    d = разобрать(отметки)
    if d.get(ЗАПЕЧАТАН):
        return []
    return [к for k, к, _ in ПУНКТЫ if not isinstance(d.get(k), bool)]


def плохие(отметки) -> list:
    """Пункты, отмеченные «не работает» → [(ключ, надпись)]."""
    d = разобрать(отметки)
    return [(k, к) for k, к, _ in ПУНКТЫ if d.get(k) is False]


def готова(отметки) -> bool:
    """Все пункты отмечены (или коробку не вскрывали) — диагностику можно считать пройденной."""
    d = разобрать(отметки)
    return bool(d.get(ЗАПЕЧАТАН)) or not не_отмечено(d)


def словами(отметки) -> str:
    """Отметки → одна строка для карточки. Пусто — диагностики не было вовсе.

    Ровно тот же текст складывает обработчик бота (`kiosk_core.диагностика_словами`): он
    пишет его в комментарий оценщика, а программа показывает на экране, и расхождение
    читалось бы как две разные диагностики."""
    d = разобрать(отметки)
    if d.get(ЗАПЕЧАТАН):
        return "Ручная диагностика: коробку не вскрывали"
    плох = [имя for _, имя in плохие(d)]
    нет = не_отмечено(d)
    сколько = len([k for k in КЛЮЧИ if isinstance(d.get(k), bool)])
    if not сколько:
        return ""
    куски = [f"Ручная диагностика ({сколько} из {len(КЛЮЧИ)})"]
    куски.append("НЕ РАБОТАЕТ: " + ", ".join(плох) if плох else "всё работает")
    if нет:
        куски.append("не отмечено: " + ", ".join(нет))
    return " · ".join(куски)


def чего_нет(состояние) -> list:
    """Состояние приёма медиа (ответ сервера) → каких медиа ещё не хватает, словами.

    Пустой список — фото и видео дошли до бота, сделку можно отправлять. Этим же списком
    программа объясняет, почему кнопка «Отправить в Оценку» пока не нажимается: «не
    хватает» без перечисления заставляет сотрудника гадать, а телефон клиента лежит на
    столе.

    Ручной диагностики здесь нет: её отмечают на экране программы, а не в боте, и спрашивать
    о ней сервер незачем — отметки и так лежат в самой программе.
    """
    с = состояние if isinstance(состояние, dict) else {}
    нет = []
    фото = int(с.get("фото") or 0)
    if фото < НУЖНО_ФОТО:
        нет.append(f"фото: {фото} из {НУЖНО_ФОТО}")
    if not с.get("видео"):
        нет.append("видео телефона")
    return нет


def ссылка_теста(ip: str, порт: int, токен: str) -> str:
    """Адрес страницы теста на телефоне клиента (мини-сервер в самом киоске).
    Отдельно от ссылки на бота: это другая сеть и другой получатель."""
    return f"http://{ip}:{int(порт)}/t/{токен}" if ip and токен else ""
